from pathlib import Path
from playwright.sync_api import sync_playwright
import json
out=Path(__file__).resolve().parents[1]
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True);reports=[]
 for key in ['border12','zone1','zone2','zone3','zone4','border23','border34']:
  context=browser.new_context(viewport={'width':1280,'height':1000});page=context.new_page();errors=[];requests=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:requests.append(r.url))
  page.goto('http://127.0.0.1:8873/docs/art-reviews/2026-11-03-layered-map/play.html?map='+key);page.wait_for_function('window.layerStreamReview?.ready',timeout=60000);page.wait_for_function('layerStreamReview.stats.pending===0',timeout=60000)
  r=page.evaluate('''()=>{const r=layerStreamReview,m=r.meta,n=r.nav;return {map:m.id,totalTiles:m.tiles.length,loaded:r.stats.loaded,stats:r.stats,view:r.camera.view,canvas:[document.querySelector('#scene').width,document.querySelector('#scene').height],hero:r.hero,goals:m.goals.map(p=>{const q=n.snap(p),d=Math.hypot((p[0]-q[0])*m.world[0],(p[1]-q[1])*m.world[1]);return {approach:d,reachable:n.path(r.hero,q).length>0,within105:d<=105};}),actorRows:!!m.actorAnimation};}''')
  page.locator('#pause').click();page.locator('#weather').uncheck();page.locator('#parallax').uncheck();page.wait_for_timeout(100)
  r['dof']=page.evaluate('''async()=>{const c=document.querySelector('#scene'),x=c.getContext('2d'),r=layerStreamReview,v=r.camera.view,px=(r.hero[0]-v.x)/v.w*c.width,py=(r.hero[1]-v.y)/v.h*c.height,h=r.meta.heroHeight/(v.h*r.meta.artSize[1])*c.height;const a=x.getImageData(0,0,c.width,c.height).data,focus=x.getImageData(Math.round(px)-3,Math.round(py-h*.45)-3,6,6).data;document.querySelector('#dof').checked=false;await new Promise(t=>setTimeout(t,100));const b=x.getImageData(0,0,c.width,c.height).data,other=x.getImageData(Math.round(px)-3,Math.round(py-h*.45)-3,6,6).data;let changed=0;for(let i=0;i<a.length;i+=4)if(Math.max(...[0,1,2].map(j=>Math.abs(a[i+j]-b[i+j])))>2)changed++;return {pixelsChangedOver2:changed,focusUnchanged:focus.every((v,i)=>v===other[i])};}''')
  page.locator('#dof').check();page.locator('#weather').check();page.locator('#parallax').check();page.wait_for_timeout(100)
  r['pauseStable']=page.evaluate('''async()=>{const c=document.querySelector('#scene'),x=c.getContext('2d'),a=x.getImageData(0,0,c.width,c.height).data;await new Promise(t=>setTimeout(t,150));const b=x.getImageData(0,0,c.width,c.height).data;return a.every((v,i)=>v===b[i]);}''')
  page.locator('#closer').click();page.wait_for_function('Math.abs(layerStreamReview.camera.zoom-layerStreamReview.meta.levels[1])<.015&&layerStreamReview.ready',timeout=60000);r['closeView']=page.evaluate('layerStreamReview.camera.view');page.locator('#scene').screenshot(path=str(out/('stream-'+key+'-cinematic.png')))
  page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(200);r['mobileOverflow']=page.evaluate('document.documentElement.scrollWidth>innerWidth');r['mobileBacking']=page.evaluate('[document.querySelector("#scene").width,document.querySelector("#scene").height]')
  r['forbiddenFullImages']=[u for u in requests if '-study.png' in u or '/img/map-zone' in u or '/img/frontier-route/zone' in u or '/img/yama-animation-v1/' in u];r['errors']=errors;reports.append(r);print(json.dumps({'map':key,'ready':True,'images':r['loaded'],'MiB':round(r['stats']['bytes']/1048576,1),'dof':r['dof'],'pause':r['pauseStable'],'unreachable':sum(not(g['reachable']and g['within105'])for g in r['goals']),'errors':errors}),flush=True);context.close()
 (out/'stream-all-browser-review.json').write_text(json.dumps({'maps':reports,'basis':'Sequential Chromium contexts, selected map only; mobile viewport is not a physical phone.'},indent=2));browser.close()
